    for b in bin(k)[3:]:
        v += 1 if b == '0' else 3
    return v

def skill():
    c = {}
    for v in range(-2, 12):
        c[v] = 0
    c[1] = 1
    for v in range(2, 12):
        c[v] = c[v - 1] + c[v - 3]
    return c[11]

def standard():
    return sum(1 for k in range(1, 1 << 13) if val(k) == 11)

def unique():
    a = {1: 1}
    for k in range(2, 1 << 13):
        a[k] = a[k // 2] + (1 if k % 2 == 0 else 3)
    return [sum(1 for k in a if a[k] == 11)]
